   143→// ==================== 牌桌类 ====================
   144→class GameTable {
   145→    constructor(id, tableNumber) {
   146→        this.id = id;
   147→        this.tableNumber = tableNumber;
   148→        this.players = new Map(); // playerId -> player info
   149→        this.spectators = new Map();
   150→        this.maxPlayers = 4;
   151→        this.gameTimer = null; // 游戏计时器
   152→
   153→        // 周期（头）相关属性
   154→        this.cycleStartTime = null; // 周期开始时间
   155→        this.cycleDuration = 60 * 60 * 1000; // 1小时（毫秒）
   156→
   157→        // 游戏流程相关属性
   158→        this.currentRound = 0; // 当前局数
   159→        this.lastWinner = null; // 上一局赢家 playerId
   160→        this.roundReadyPlayers = new Set(); // 每局结束后已准备的玩家
   161→
   162→        // 骰子状态
   163→        this.diceState = {
   164→            firstRoll: null, // 第一次骰子结果 { playerId, values: [d1, d2] }
   165→            secondRoll: null, // 第二次骰子结果 { playerId, values: [d1, d2] }
   166→            currentRoller: null, // 当前应该掷骰子的人
   167→            rollPhase: 0 // 0=未开始, 1=等待第一次, 2=等待第二次, 3=完成
   168→        };
   169→
   170→        this.gameState = {
   171→            started: false,
   172→            currentPlayer: 0, // 0-3, 当前出牌玩家索引
   173→            dealer: 0, // 庄家索引
   174→            dealerSeat: 1, // 庄家座位号（1-4）
   175→            deck: [], // 牌堆
   176→            hands: {}, // playerId -> cards[]
   177→            wildCard: null, // 万能牌
   178→            discardedPile: [], // 打出的牌
   179→            showedCards: {}, // playerId -> { fa: [], gang: [] }
   180→            faUsed: {}, // playerId -> 玩家是否已换过发
   181→            lastDrawn: null, // 最后摸的牌
   182→            gameStartTime: null, // 游戏开始时间
   183→            totalGameTime: 0, // 游戏总时长（秒）
   184→            roundPhase: 'waiting' // waiting=等待准备, dice=掷骰子阶段, playing=游戏中, ended=本局结束
   185→        };
   186→    }
   187→
   188→    // 获取按座位排序的玩家ID数组
   189→    getSortedPlayerIds() {
   190→        return Array.from(this.players.entries())
   191→            .sort((a, b) => a[1].seatNum - b[1].seatNum)
   192→            .map(([id]) => id);
   193→    }
   194→
   195→    // 添加玩家
   196→    addPlayer(ws, playerId, playerName, seatNum = null) {
   197→        if (this.players.size >= this.maxPlayers) return false;
   198→        if (this.gameState.started) return false;
   199→
   200→        let actualSeat;
   201→        if (seatNum !== null && seatNum >= 1 && seatNum <= 4) {
   202→            const occupied = Array.from(this.players.values()).some(p => p.seatNum === seatNum);
   203→            if (occupied) return false;
   204→            actualSeat = seatNum;
   205→        } else {
   206→            const occupiedSeats = new Set(Array.from(this.players.values()).map(p => p.seatNum));
   207→            for (let i = 1; i <= 4; i++) {
   208→                if (!occupiedSeats.has(i)) {
   209→                    actualSeat = i;
   210→                    break;
   211→                }
   212→            }
   213→        }
   214→
   215→        this.players.set(playerId, {
   216→            ws,
   217→            id: playerId,
   218→            name: playerName,
   219→            seatNum: actualSeat,
   220→            ready: false,
   221→            isAI: false
   222→        });
   223→
   224→        return true;
   225→    }
   226→
   227→    // 移除玩家
   228→    removePlayer(playerId) {
   229→        this.players.delete(playerId);
   230→        return this.players.size === 0;
   231→    }
   232→
   233→    // 检查是否所有玩家都已断开连接
   234→    isAllPlayersDisconnected() {
   235→        if (this.players.size === 0) return true;
   236→        for (const player of this.players.values()) {
   237→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   238→                return false;
   239→            }
   240→        }
   241→        return true;
   242→    }
   243→
   244→    // 设置准备状态
   245→    setPlayerReady(playerId, ready) {
   246→        const player = this.players.get(playerId);
   247→        if (player) {
   248→            player.ready = ready;
   249→            this.broadcastPlayerList();
   250→            this.checkStartGame();
   251→        }
   252→    }
   253→
   254→    // 检查是否可以开始游戏
   255→    checkStartGame() {
   256→        const allReady = Array.from(this.players.values()).every(p => p.ready);
   257→
   258→        if (this.gameState.roundPhase === 'waiting' || !this.gameState.started) {
   259→            // 新游戏或新一周期的开始
   260→            if (allReady && this.players.size >= 1) {
   261→                // 检查是否是新周期
   262→                if (!this.cycleStartTime || (Date.now() - this.cycleStartTime >= this.cycleDuration)) {
   263→                    this.cycleStartTime = Date.now();
   264→                    this.currentRound = 0;
   265→                    console.log(`牌桌${this.tableNumber} 开始新周期`);
   266→                }
   267→                this.startDicePhase();
   268→            }
   269→        } else if (this.gameState.roundPhase === 'ended') {
   270→            // 局间准备，检查所有人是否都准备了
   271→            const allRoundReady = this.roundReadyPlayers.size === this.players.size;
   272→            if (allRoundReady) {
   273→                this.startDicePhase();
   274→            }
   275→        }
   276→    }
   277→
   278→    // 开始掷骰子阶段
   279→    startDicePhase() {
   280→        // 先初始化牌堆和庄家
   281→        this.initDeckAndDealer();
   282→
   283→        this.gameState.roundPhase = 'dice';
   284→        this.diceState = {
   285→            firstRoll: null,
   286→            secondRoll: null,
   287→            currentRoller: null,
   288→            rollPhase: 1
   289→        };
   290→
   291→        // 确定第一次掷骰子的人
   292→        const firstRollerId = this.getFirstRoller();
   293→        const firstRoller = this.players.get(firstRollerId);
   294→        this.diceState.currentRoller = firstRollerId;
   295→
   296→        this.broadcastMessage(`🎲 第${this.currentRound + 1}局开始！请 ${firstRoller.name} 掷骰子`);
   297→
   298→        // 通知所有人骰子状态
   299→        this.broadcastDiceState();
   300→
   301→        // 检查是否轮到AI掷骰子
   302→        setTimeout(() => this.checkAITurn(), 500);
   303→    }
   304→
   305→    // 获取第一次掷骰子的人
   306→    getFirstRoller() {
   307→        const playerIds = this.getSortedPlayerIds();
   308→
   309→        if (this.currentRound === 0) {
   310→            // 周期第一局：座东的玩家坐庄并先掷骰子
   311→            // 座位与方位对应：1号位=南，2号位=东，3号位=西，4号位=北
   312→            const dongPlayer = Array.from(this.players.values()).find(p => p.seatNum === 2);
   313→            if (dongPlayer) {
   314→                this.gameState.dealerSeat = 2;
   315→                this.gameState.dealer = playerIds.indexOf(dongPlayer.id);
   316→                return dongPlayer.id;
   317→            }
   318→        } else {
   319→            // 后续局：上一局胡牌者掷第一次骰子
   320→            if (this.lastWinner) {
   321→                // 上局赢家成为庄家
   322→                const winner = this.players.get(this.lastWinner);
   323→                if (winner) {
   324→                    this.gameState.dealerSeat = winner.seatNum;
   325→                    this.gameState.dealer = playerIds.indexOf(this.lastWinner);
   326→                }
   327→                return this.lastWinner;
   328→            }
   329→        }
   330→
   331→        // 默认返回第一个玩家
   332→        return playerIds[0];
   333→    }
   334→
   335→    // 获取第二次掷骰子的人（根据第一次骰子点数和，逆时针数）
   336→    getSecondRoller(firstSum) {
   337→        const playerIds = this.getSortedPlayerIds();
   338→        const firstRollerIndex = playerIds.indexOf(this.diceState.firstRoll.playerId);
   339→
   340→        // playerIds 是 [座位1, 座位2, 座位3, 座位4]（顺时针：东→南→西→北）
   341→        // 逆时针顺序：东(0)→北(3)→西(2)→南(1)→东(0)
   342→        // 逆时针移动一步 = 索引 -1（或 +3 mod 4）
   343→        // 数firstSum步，从1开始数（所以-1）
   344→        const secondRollerIndex = (firstRollerIndex - (firstSum - 1) % 4 + 4) % 4;
   345→        return playerIds[secondRollerIndex];
   346→    }
   347→
   348→    // 掷骰子
   349→    rollDice(playerId, values) {
   350→        console.log(`rollDice 被调用: playerId=${playerId}, values=${JSON.stringify(values)}, currentRoller=${this.diceState.currentRoller}, rollPhase=${this.diceState.rollPhase}`);
   351→
   352→        if (this.diceState.currentRoller !== playerId) {
   353→            console.log(`不是你的回合掷骰子: currentRoller=${this.diceState.currentRoller}, playerId=${playerId}`);
   354→            return { success: false, message: '不是你的回合掷骰子' };
   355→        }
   356→
   357→        const player = this.players.get(playerId);
   358→        if (!player) {
   359→            console.log(`找不到玩家: ${playerId}`);
   360→            return { success: false, message: '玩家不存在' };
   361→        }
   362→
   363→        if (this.diceState.rollPhase === 1) {
   364→            // 第一次掷骰子
   365→            console.log(`第一次掷骰子: ${player.name}`);
   366→            this.diceState.firstRoll = { playerId, playerName: player.name, values };
   367→            this.diceState.rollPhase = 2;
   368→
   369→            // 根据第一次骰子点数和，确定第二次掷骰子的人
   370→            const firstSum = values[0] + values[1];
   371→            console.log(`计算第二次掷骰者: firstSum=${firstSum}`);
   372→            const secondRollerId = this.getSecondRoller(firstSum);
   373→            console.log(`第二次掷骰者ID: ${secondRollerId}`);
   374→            this.diceState.currentRoller = secondRollerId;
   375→            const secondRoller = this.players.get(secondRollerId);
   376→
   377→            this.broadcastMessage(`🎲 ${player.name} 掷出 ${values[0]}+${values[1]}=${firstSum} 点`);
   378→            this.broadcastMessage(`🎲 从${player.name}逆时针数${firstSum}步，请 ${secondRoller.name} 掷第二次骰子`);
   379→
   380→            this.broadcastDiceState();
   381→
   382→            // 检查是否轮到AI掷第二次骰子
   383→            setTimeout(() => this.checkAITurn(), 500);
   384→
   385→            return { success: true, phase: 1, values };
   386→
   387→        } else if (this.diceState.rollPhase === 2) {
   388→            // 第二次掷骰子
   389→            this.diceState.secondRoll = { playerId, playerName: player.name, values };
   390→            this.diceState.rollPhase = 3;
   391→
   392→            this.broadcastMessage(`🎲 ${player.name} 掷出 ${values[0]}+${values[1]}=${values[0]+values[1]} 点`);
   393→
   394→            // 确定抓牌位置和癞子
   395→            this.determineWildCard();
   396→
   397→            // 开始发牌
   398→            setTimeout(() => {
   399→                this.startDealCards();
   400→            }, 1000);
   401→
   402→            this.broadcastDiceState();
   403→
   404→            return { success: true, phase: 2, values };
   405→        }
   406→
   407→        return { success: false, message: '骰子阶段错误' };
   408→    }
   409→
   410→    // 根据亮牌确定癞子（下一张牌）
   411→    getWildCardFromShown(shownCard) {
   412→        // 普通牌（筒条万）：1-9循环
   413→        if (shownCard.type === 'number') {
   414→            const nextRank = shownCard.rank >= 9 ? 1 : shownCard.rank + 1;
   415→            return {
   416→                suit: shownCard.suit,
   417→                rank: nextRank,
   418→                type: 'number'
   419→            };
   420→        }
   421→        // 风牌：东南西北循环
   422→        if (shownCard.type === 'wind') {
   423→            const windOrder = ['东', '南', '西', '北'];
   424→            const currentIndex = windOrder.indexOf(shownCard.rank);
   425→            const nextIndex = (currentIndex + 1) % 4;
   426→            return {
   427→                suit: '风',
   428→                rank: windOrder[nextIndex],
   429→                type: 'wind'
   430→            };
   431→        }
   432→        // 箭牌：中发白循环
   433→        if (shownCard.type === 'arrow') {
   434→            const arrowOrder = ['中', '发', '白'];
   435→            const currentIndex = arrowOrder.indexOf(shownCard.rank);
   436→            const nextIndex = (currentIndex + 1) % 3;
   437→            return {
   438→                suit: '箭',
   439→                rank: arrowOrder[nextIndex],
   440→                type: 'arrow'
   441→            };
   442→        }
   443→        return null;
   444→    }
   445→
   446→    // 确定万能牌（癞子）和抓牌位置 - 根据骰子结果
   447→    determineWildCard() {
   448→        const firstSum = this.diceState.firstRoll.values[0] + this.diceState.firstRoll.values[1];
   449→        const secondSum = this.diceState.secondRoll.values[0] + this.diceState.secondRoll.values[1];
   450→        const total = firstSum + secondSum;
   451→
   452→        console.log(`第1次骰子: ${firstSum}, 第2次骰子: ${secondSum}, 总计: ${total}`);
   453→
   454→        // 牌墙布局：每个玩家面前17墩牌（每墩2张），按逆时针排列
   455→        // 座位1(东) -> 座位4(北) -> 座位3(西) -> 座位2(南) -> 座位1(东)
   456→        // 牌墙索引：0-33(东), 34-67(北), 68-101(西), 102-135(南)
   457→        // 每个方位17墩，每墩2张牌
   458→
   459→        const firstRollerSeat = this.players.get(this.diceState.firstRoll.playerId)?.seatNum || 1;
   460→
   461→        // 根据第一次骰子确定从哪个方位开始数
   462→        // 逆时针方向：东(1) -> 北(4) -> 西(3) -> 南(2) -> 东(1)
   463→        const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
   464→        const directionOrder = [1, 4, 3, 2]; // 逆时针顺序
   465→
   466→        // 第1次骰子点数决定从哪个方位开始（从掷骰者的方位开始数）
   467→        const startDirectionIndex = directionOrder.indexOf(firstRollerSeat);
   468→        const countDirection = (startDirectionIndex + firstSum - 1) % 4;
   469→        const startDirection = directionOrder[countDirection];
   470→
   471→        console.log(`开始方位: ${seatToDirection[startDirection]} (座位${startDirection})`);
   472→
   473→        // 计算从开始方位最左边数起，数total墩
   474→        // 每个方位17墩
   475→        const pilesPerDirection = 17;
   476→        let remainingPiles = total;
   477→        let currentDirection = startDirection;
   478→        let directionIdx = directionOrder.indexOf(currentDirection);
   479→
   480→        // 数牌墩
   481→        while (remainingPiles > pilesPerDirection) {
   482→            remainingPiles -= pilesPerDirection;
   483→            directionIdx = (directionIdx + 1) % 4;
   484→            currentDirection = directionOrder[directionIdx];
   485→        }
   486→
   487→        // 确定抓牌起始位置
   488→        // 抓牌从第remainingPiles墩的下一墩开始
   489→        const drawPile = remainingPiles; // 第几墩（1-17）
   490→        const drawDirection = currentDirection;
   491→
   492→        console.log(`抓牌位置: ${seatToDirection[drawDirection]}方第${drawPile}墩后开始`);
   493→
   494→        // 确定亮牌位置
   495→        // 抓牌那墩的逆时针玩家面前的牌墩从右往左数第一次骰子的数量
   496→        const drawDirectionIdx = directionOrder.indexOf(drawDirection);
   497→        const shownDirectionIdx = (drawDirectionIdx + 1) % 4; // 逆时针下一个
   498→        const shownDirection = directionOrder[shownDirectionIdx];
   499→
   500→        // 从右往左数第firstSum墩
   501→        const shownPile = pilesPerDirection - firstSum + 1; // 从右往左数
   502→
   503→        console.log(`亮牌位置: ${seatToDirection[shownDirection]}方第${shownPile}墩（从右往左数第${firstSum}墩）`);
   504→
   505→        // 计算牌堆中的实际索引
