   604→        // playerIds 是 [座位1, 座位2, 座位3, 座位4]（顺时针）
   605→        // 逆时针需要调整为 [座位1, 座位4, 座位3, 座位2]
   606→        const counterClockwiseIds = [
   607→            playerIds[0], // 座位1(东)
   608→            playerIds[3], // 座位4(北)
