   787→    // 排序手牌
   788→    sortHand(playerId) {
   789→        const hand = this.gameState.hands[playerId];
   790→        if (!hand) return;
   791→
   792→        const suitOrder = { '筒': 0, '条': 1, '万': 2, '风': 3, '箭': 4 };
   793→        const windOrder = { '东': 0, '南': 1, '西': 2, '北': 3 };
   794→        const arrowOrder = { '中': 0, '发': 1, '白': 2 };
   795→
   796→        hand.sort((a, b) => {
   797→            // 万能牌放最后
   798→            if (this.isWildCard(a) && !this.isWildCard(b)) return 1;
   799→            if (!this.isWildCard(a) && this.isWildCard(b)) return -1;
   800→
   801→            const suitA = suitOrder[a.suit] ?? 5;
   802→            const suitB = suitOrder[b.suit] ?? 5;
   803→            if (suitA !== suitB) return suitA - suitB;
   804→
   805→            if (a.type === 'number' && b.type === 'number') {
   806→                return a.rank - b.rank;
   807→            } else if (a.type === 'wind' && b.type === 'wind') {
   808→                return (windOrder[a.rank] ?? 0) - (windOrder[b.rank] ?? 0);
   809→            } else if (a.type === 'arrow' && b.type === 'arrow') {
   810→                return (arrowOrder[a.rank] ?? 0) - (arrowOrder[b.rank] ?? 0);
   811→            }
   812→            return 0;
   813→        });
   814→    }
