   820→
   821→        // 相同牌是万能牌
   822→        if (card.suit === wild.suit && card.rank === wild.rank) return true;
   823→        // 红中也是万能牌
   824→        if (card.type === 'arrow' && card.rank === '中') return true;
   825→
   826→        return false;
   827→    }
