   847→    // 更新牌墙状态
   848→    updateWallState() {
   849→        // 计算已抓取的牌数
   850→        const initialCards = 136 - 1; // 总牌数减去亮牌
   851→        const remainingCards = this.gameState.deck.length;
   852→        const drawnCards = initialCards - remainingCards;
   853→
   854→        // 牌墙初始状态：每个方位17墩（34张）
   855→        const initialPiles = { 1: 17, 2: 17, 3: 17, 4: 17 };
   856→
   857→        // 抓牌顺序（顺时针）：根据抓牌起始位置确定
   858→        // drawInfo.startDirection 是抓牌起始方位（1-4）
   859→        const drawInfo = this.gameState.drawInfo;
   860→        if (!drawInfo) {
   861→            this.gameState.wallState = initialPiles;
   862→            return;
   863→        }
   864→
   865→        const startDir = drawInfo.startDirection;
   866→        // 顺时针顺序：东(1)→南(2)→西(3)→北(4)
   867→        // 但实际抓牌是从起始墩的下一墩开始
   868→        const startPile = drawInfo.drawPile || 0;
   869→
   870→        // 计算已抓取的牌墩数（每墩2张）
   871→        const drawnPiles = Math.floor(drawnCards / 2);
   872→        const singleCard = drawnCards % 2; // 是否有单张
   873→
   874→        // 从起始方位开始，顺时针分配已抓取的牌墩
   875→        // 先计算起始方位之前要跳过的牌墩
   876→        const directionOrder = [1, 2, 3, 4]; // 顺时针：东南西北
   877→        const startIdx = directionOrder.indexOf(startDir);
   878→
   879→        // 起始方位之前已抓取的牌墩数（从起始墩开始抓）
   880→        // 起始方位剩余的牌墩 = 17 - startPile
   881→        let wallState = { 1: 17, 2: 17, 3: 17, 4: 17 };
   882→
   883→        // 标记起始方位已抓取的牌墩
   884→        wallState[startDir] = startPile;
   885→
   886→        // 剩余需要抓取的牌墩
   887→        let remainingPilesToDraw = drawnPiles;
   888→        if (wallState[startDir] < 17) {
   889→            // 起始方位已抓了一些
   890→        }
   891→
   892→        // 按顺时针方向减少牌墩
   893→        let currentDirIdx = startIdx;
   894→        while (remainingPilesToDraw > 0) {
   895→            const available = wallState[directionOrder[currentDirIdx]];
   896→            if (remainingPilesToDraw >= available) {
   897→                wallState[directionOrder[currentDirIdx]] = 0;
   898→                remainingPilesToDraw -= available;
   899→            } else {
   900→                wallState[directionOrder[currentDirIdx]] -= remainingPilesToDraw;
   901→                remainingPilesToDraw = 0;
   902→            }
   903→            currentDirIdx = (currentDirIdx + 1) % 4;
   904→        }
   905→
   906→        this.gameState.wallState = wallState;
   907→    }
