   932→    // 换牌（发或红中）
   933→    changeFa(playerId) {
   934→        // 检查是否已换过
   935→        if (this.gameState.faUsed[playerId]) return false;
   936→
   937→        const hand = this.gameState.hands[playerId];
   938→        if (!hand) return false;
