   941→        const isWildFa = wild && wild.type === 'arrow' && wild.rank === '发';
   942→
   943→        // 如果万能牌是"发"，找红中；否则找"发"
   944→        let targetRank = isWildFa ? '中' : '发';
   945→        const faIndex = hand.findIndex(c => c.type === 'arrow' && c.rank === targetRank);
   946→        if (faIndex === -1) return false;
   947→
   948→        // 移出牌到展示区
   949→        const faCard = hand.splice(faIndex, 1)[0];
   950→        this.gameState.showedCards[playerId].fa.push(faCard);
   951→        this.gameState.faUsed[playerId] = true;
   952→
   953→        // 摸一张新牌
