   959→    // 暗杠
   960→    doGang(playerId, cardId) {
   961→        const hand = this.gameState.hands[playerId];
   962→        if (!hand) return false;
   963→
   964→        // 找到这张牌
   965→        const targetCard = hand.find(c => c.id === cardId);
   966→        if (!targetCard) return false;
   967→
   968→        // 找所有相同的牌（不包括万能牌替代）
   969→        const sameCards = hand.filter(c =>
   970→            c.suit === targetCard.suit && c.rank === targetCard.rank
   971→        );
   972→
   973→        if (sameCards.length !== 4) return false;
   974→
   975→        // 移除这4张牌
   976→        this.gameState.hands[playerId] = hand.filter(c =>
   977→            !(c.suit === targetCard.suit && c.rank === targetCard.rank)
   978→        );
   979→
   980→        // 加入展示区
   981→        this.gameState.showedCards[playerId].gang.push(sameCards);
   982→
   983→        return sameCards;
   984→    }
