   986→    // 检查是否可以暗杠
   987→    canGang(playerId) {
   988→        const hand = this.gameState.hands[playerId];
   989→        if (!hand) return [];
   990→
   991→        const counts = {};
   992→        for (const card of hand) {
   993→            const key = `${card.suit}_${card.rank}`;
   994→            counts[key] = (counts[key] || 0) + 1;
   995→        }
   996→
   997→        const gangable = [];
   998→        for (const [key, count] of Object.entries(counts)) {
   999→            if (count === 4) {
  1000→                const [suit, rank] = key.split('_');
  1001→                gangable.push({ suit, rank });
  1002→            }
  1003→        }
  1004→
  1005→        return gangable;
  1006→    }
