// 开始发牌
startDealCards() {
    this.currentRound++;
    this.gameState.roundPhase = 'playing';
    this.roundReadyPlayers.clear();

    // 重置玩家准备状态（局间准备用）
    for (const player of this.players.values()) {
        player.ready = false;
    }

    // 重置每局游戏状态
    this.gameState.discardedPile = [];
    this.gameState.showedCards = {};
    this.gameState.faUsed = {};
    this.gameState.lastDrawn = null;

    // 初始化牌墙状态：每个方位17墩
    this.gameState.wallState = { 1: 17, 2: 17, 3: 17, 4: 17 };

    // 初始化手牌
    const playerIds = this.getSortedPlayerIds();
    for (const pid of playerIds) {
        this.gameState.hands[pid] = [];
        this.gameState.showedCards[pid] = { fa: [], gang: [] };
        this.gameState.faUsed[pid] = false;
    }

    // 逆时针顺序：东(1)→北(4)→西(3)→南(2)
    // playerIds 是 [座位1, 座位2, 座位3, 座位4]（顺时针）
    // 逆时针需要调整为 [座位1, 座位4, 座位3, 座位2]
    const counterClockwiseIds = [
        playerIds[0], // 座位1(东)
        playerIds[3], // 座位4(北)
        playerIds[2], // 座位3(西)
        playerIds[1]  // 座位2(南)
    ];

    // 发牌：每人4张×3轮，然后每人1张，庄家多1张
    // 每人4张×3轮（逆时针顺序）- 相当于每人2墩×3轮
    for (let round = 0; round < 3; round++) {
        for (const pid of counterClockwiseIds) {
            for (let i = 0; i < 4; i++) {
                const card = this.gameState.deck.pop();
                if (card) this.gameState.hands[pid].push(card);
            }
        }
    }

    // 每人1张（逆时针顺序）
    for (const pid of counterClockwiseIds) {
        const card = this.gameState.deck.pop();
        if (card) this.gameState.hands[pid].push(card);
    }

    // 庄家多拿1张
    const dealerPid = playerIds[this.gameState.dealer];
    const extraCard = this.gameState.deck.pop();
    if (extraCard) this.gameState.hands[dealerPid].push(extraCard);

    // 更新牌墙状态
    this.updateWallState();

    // 庄家先出牌
    this.gameState.currentPlayer = this.gameState.dealer;

    // 排序手牌
    for (const pid of playerIds) {
        this.sortHand(pid);
    }

    console.log(`牌桌${this.tableNumber} 第${this.currentRound}局开始，庄家座位: ${this.gameState.dealerSeat}，万能牌: ${cardName(this.gameState.wildCard)}`);

    // 直接发送游戏状态（删除发牌动画）
    this.broadcastGameState();
    // 检查是否轮到AI出牌
    this.checkAITurn();
}

