// 根据第一次骰子确定从哪个方位开始数
// 逆时针方向：东(1) -> 北(4) -> 西(3) -> 南(2) -> 东(1)
const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
const directionOrder = [1, 4, 3, 2]; // 逆时针顺序

// 第1次骰子点数决定从哪个方位开始（从掷骰者的方位开始数）
const startDirectionIndex = directionOrder.indexOf(firstRollerSeat);
const countDirection = (startDirectionIndex + firstSum - 1) % 4;
const startDirection = directionOrder[countDirection];

console.log(`开始方位: ${seatToDirection[startDirection]} (座位${startDirection})`);

// 计算从开始方位最左边数起，数total墩
// 每个方位17墩
const pilesPerDirection = 17;
let remainingPiles = total;
let currentDirection = startDirection;
let directionIdx = directionOrder.indexOf(currentDirection);

// 数牌墩
while (remainingPiles > pilesPerDirection) {
    remainingPiles -= pilesPerDirection;
    directionIdx = (directionIdx + 1) % 4;
    currentDirection = directionOrder[directionIdx];
}

// 确定抓牌起始位置
// 抓牌从第remainingPiles墩的下一墩开始
const drawPile = remainingPiles; // 第几墩（1-17）
const drawDirection = currentDirection;

console.log(`抓牌位置: ${seatToDirection[drawDirection]}方第${drawPile}墩后开始`);

// 确定亮牌位置
// 抓牌那墩的逆时针玩家面前的牌墩从右往左数第一次骰子的数量
const drawDirectionIdx = directionOrder.indexOf(drawDirection);
const shownDirectionIdx = (drawDirectionIdx + 1) % 4; // 逆时针下一个
const shownDirection = directionOrder[shownDirectionIdx];

// 从右往左数第firstSum墩
const shownPile = pilesPerDirection - firstSum + 1; // 从右往左数

console.log(`亮牌位置: ${seatToDirection[shownDirection]}方第${shownPile}墩（从右往左数第${firstSum}墩）`);

// 计算牌堆中的实际索引
// 牌墙按 [东17墩][北17墩][西17墩][南17墩] 排列
const directionToOffset = { 1: 0, 4: 17, 3: 34, 2: 51 }; // 座位到牌墩偏移
const shownPileIndex = directionToOffset[shownDirection] + (shownPile - 1);

// 每墩2张牌，取上面那张（索引*2）
const shownCardIndex = shownPileIndex * 2;

// 获取亮牌
let shownCard = null;
if (shownCardIndex >= 0 && shownCardIndex < this.gameState.deck.length) {
    shownCard = this.gameState.deck[shownCardIndex];
    console.log(`亮牌索引: ${shownCardIndex}, 亮牌: ${cardName(shownCard)}`);

    // 从牌堆中移除亮牌（玩家不可获取）
    this.gameState.shownCard = shownCard;
    this.gameState.deck.splice(shownCardIndex, 1);
    console.log(`亮牌已移除，剩余牌数: ${this.gameState.deck.length}`);

    // 根据亮牌确定癞子
    const wildCardInfo = this.getWildCardFromShown(shownCard);
    if (wildCardInfo) {
        // 在牌堆中找到对应的癞子牌
        this.gameState.wildCard = this.gameState.deck.find(c =>
            c.suit === wildCardInfo.suit && c.rank === wildCardInfo.rank
        ) || wildCardInfo; // 如果找不到，使用信息对象
        console.log(`癞子: ${cardName(this.gameState.wildCard)} (根据亮牌${cardName(shownCard)}确定)`);
    }
} else {
    // 备用：随机选择
    const wildIndex = total % this.gameState.deck.length;
    this.gameState.wildCard = this.gameState.deck[wildIndex];
    console.log(`亮牌索引超出范围，使用备用计算: ${cardName(this.gameState.wildCard)}`);
}

// 保存抓牌信息用于发牌
this.gameState.drawInfo = {
    startDirection,
    drawDirection,
    drawPile,
    totalPiles: total,
    shownCard,
    shownDirection,
    shownPile
};

