// 更新牌墙状态
updateWallState() {
    // 计算已抓取的牌数（初始136张，减去亮牌1张，减去牌堆剩余）
    const initialCards = 136 - 1; // 总牌数减去亮牌
    const remainingCards = this.gameState.deck.length;
    const drawnCards = initialCards - remainingCards;

    // 牌墙初始状态：每个方位17墩
    // 初始化为满牌状态
    let wallState = { 1: 17, 2: 17, 3: 17, 4: 17 };

    // 根据 drawInfo 确定抓牌起始位置
    const drawInfo = this.gameState.drawInfo;
    if (!drawInfo || !drawInfo.drawDirection) {
        this.gameState.wallState = wallState;
        return;
    }

    // 抓牌方向（顺时针）：东(1)→南(2)→西(3)→北(4)
    const directionOrder = [1, 2, 3, 4];
    const drawDir = drawInfo.drawDirection;  // 使用 drawDirection（实际抓牌起始方位）
    const drawIdx = directionOrder.indexOf(drawDir);

    // 计算起始方位之前跳过的牌墩数（被跳过的部分保持17墩）
    const skipPiles = drawInfo.drawPile || 0;

    // 计算已抓取的牌墩数（每墩2张）
    const drawnPiles = Math.floor(drawnCards / 2);
    const hasHalfPile = drawnCards % 2; // 是否有半墩（单张）

    console.log(`更新牌墙: 已抓${drawnCards}张=${drawnPiles}墩+${hasHalfPile}张, 抓牌方位${drawDir}, 跳过${skipPiles}墩`);

    // 从抓牌方位开始，顺时针方向抓牌
    // 抓牌方位先抓完剩余的牌墩（17 - skipPiles）
    let remainingPilesToDraw = drawnPiles;

    // 首先处理抓牌方位
    // 抓牌方位可抓的牌墩 = 17 - skipPiles（跳过的部分保持满）
    const drawAvailablePiles = 17 - skipPiles;

    if (remainingPilesToDraw > 0) {
        if (remainingPilesToDraw >= drawAvailablePiles) {
            // 抓牌方位抓完，剩余为跳过的牌墩数
            wallState[drawDir] = skipPiles;
            remainingPilesToDraw -= drawAvailablePiles;
        } else {
            // 抓牌方位还剩一些
            wallState[drawDir] = skipPiles + (drawAvailablePiles - remainingPilesToDraw);
            remainingPilesToDraw = 0;
        }
    }

    // 然后顺时针处理其他方位
    let currentDirIdx = (drawIdx + 1) % 4;
    while (remainingPilesToDraw > 0 && currentDirIdx !== drawIdx) {
        const currentDir = directionOrder[currentDirIdx];
        if (remainingPilesToDraw >= 17) {
            // 这个方位的牌墩全部抓完
            wallState[currentDir] = 0;
            remainingPilesToDraw -= 17;
        } else {
            // 这个方位还剩一些
            wallState[currentDir] = 17 - remainingPilesToDraw;
            remainingPilesToDraw = 0;
        }
        currentDirIdx = (currentDirIdx + 1) % 4;
    }

    this.gameState.wallState = wallState;

