// 渲染牌墙
function renderWall(shownInfo = null) {
    const directions = ['North', 'South', 'West', 'East'];

    // 获取当前玩家的座位号（从全局变量或gameState中获取）
    let mySeatNum = 1;
    if (typeof gameState !== 'undefined' && gameState.playerInfo) {
        for (const [pid, info] of Object.entries(gameState.playerInfo)) {
            // 找到当前玩家
            if (pid === Object.keys(gameState.playerInfo)[myIndex]) {
                mySeatNum = info.seatNum;
                break;
            }
        }
    }

    // 根据玩家视角计算各方位对应的座位号
    // South(下) = 自己, North(上) = 对家, West(左) = 上家, East(右) = 下家
    // 麻将中，上家是逆时针方向（座位号+1），下家是顺时针方向（座位号-1或+3）
    const seatMap = {
        'South': mySeatNum,                    // 下 = 自己
        'North': (mySeatNum + 1) % 4 + 1,      // 上 = 对家 (座位号+2, 即+1后mod4再+1)
        'West': (mySeatNum) % 4 + 1,           // 左 = 上家 (座位号+1)
        'East': (mySeatNum + 2) % 4 + 1        // 右 = 下家 (座位号-1, 即+3 mod4, 但用+2再+1)
    };

    // 修正计算：对家 = (mySeatNum + 2 - 1) % 4 + 1 = (mySeatNum + 1) % 4 + 1
    // 修正计算：上家 = (mySeatNum + 1 - 1) % 4 + 1 = mySeatNum % 4 + 1
    // 修正计算：下家 = (mySeatNum + 3 - 1) % 4 + 1 = (mySeatNum + 2) % 4 + 1
    seatMap['South'] = mySeatNum;
