   462→    // 确定万能牌（癞子）和抓牌位置 - 根据骰子结果
   463→    determineWildCard() {
   464→        const firstSum = this.diceState.firstRoll.values[0] + this.diceState.firstRoll.values[1];
   465→        const secondSum = this.diceState.secondRoll.values[0] + this.diceState.secondRoll.values[1];
   466→        const total = firstSum + secondSum;
   467→
   468→        console.log(`第1次骰子: ${firstSum}, 第2次骰子: ${secondSum}, 总计: ${total}`);
   469→
   470→        // 牌墙布局：每个玩家面前17墩牌（每墩2张），按逆时针排列
   471→        // 座位1(东) -> 座位4(北) -> 座位3(西) -> 座位2(南) -> 座位1(东)
   472→        // 牌墙索引：0-33(东), 34-67(北), 68-101(西), 102-135(南)
   473→        // 每个方位17墩，每墩2张牌
   474→
   475→        const firstRollerSeat = this.players.get(this.diceState.firstRoll.playerId)?.seatNum || 1;
   476→
   477→        // 根据第一次骰子确定从哪个方位开始数
   478→        // 逆时针方向：东(1) -> 北(4) -> 西(3) -> 南(2) -> 东(1)
   479→        const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
   480→        const directionOrder = [1, 4, 3, 2]; // 逆时针顺序
   481→
   482→        // 第1次骰子点数决定从哪个方位开始（从掷骰者的方位开始数）
   483→        const startDirectionIndex = directionOrder.indexOf(firstRollerSeat);
   484→        const countDirection = (startDirectionIndex + firstSum - 1) % 4;
   485→        const startDirection = directionOrder[countDirection];
   486→
   487→        console.log(`开始方位: ${seatToDirection[startDirection]} (座位${startDirection})`);
   488→
   489→        // 计算从开始方位最左边数起，数total墩
   490→        // 每个方位17墩
   491→        const pilesPerDirection = 17;
   492→        let remainingPiles = total;
   493→        let currentDirection = startDirection;
   494→        let directionIdx = directionOrder.indexOf(currentDirection);
   495→
   496→        // 数牌墩
   497→        while (remainingPiles > pilesPerDirection) {
   498→            remainingPiles -= pilesPerDirection;
   499→            directionIdx = (directionIdx + 1) % 4;
   500→            currentDirection = directionOrder[directionIdx];
   501→        }
   502→
   503→        // 确定抓牌起始位置
   504→        // 抓牌从第remainingPiles墩的下一墩开始
   505→        const drawPile = remainingPiles; // 第几墩（1-17）
   506→        const drawDirection = currentDirection;
   507→
   508→        console.log(`抓牌位置: ${seatToDirection[drawDirection]}方第${drawPile}墩后开始`);
   509→
   510→        // 确定亮牌位置
   511→        // 抓牌那墩的逆时针玩家面前的牌墩从右往左数第一次骰子的数量
   512→        const drawDirectionIdx = directionOrder.indexOf(drawDirection);
   513→        const shownDirectionIdx = (drawDirectionIdx + 1) % 4; // 逆时针下一个
   514→        const shownDirection = directionOrder[shownDirectionIdx];
   515→
   516→        // 从右往左数第firstSum墩
   517→        const shownPile = pilesPerDirection - firstSum + 1; // 从右往左数
   518→
   519→        console.log(`亮牌位置: ${seatToDirection[shownDirection]}方第${shownPile}墩（从右往左数第${firstSum}墩）`);
   520→
   521→        // 计算牌堆中的实际索引
   522→        // 牌墙按 [东17墩][北17墩][西17墩][南17墩] 排列
   523→        const directionToOffset = { 1: 0, 4: 17, 3: 34, 2: 51 }; // 座位到牌墩偏移
   524→        const shownPileIndex = directionToOffset[shownDirection] + (shownPile - 1);
   525→
   526→        // 每墩2张牌，取上面那张（索引*2）
   527→        const shownCardIndex = shownPileIndex * 2;
   528→
   529→        // 获取亮牌
   530→        let shownCard = null;
   531→        if (shownCardIndex >= 0 && shownCardIndex < this.gameState.deck.length) {
   532→            shownCard = this.gameState.deck[shownCardIndex];
   533→            console.log(`亮牌索引: ${shownCardIndex}, 亮牌: ${cardName(shownCard)}`);
   534→
   535→            // 从牌堆中移除亮牌（玩家不可获取）
   536→            this.gameState.shownCard = shownCard;
   537→            this.gameState.deck.splice(shownCardIndex, 1);
   538→            console.log(`亮牌已移除，剩余牌数: ${this.gameState.deck.length}`);
   539→
   540→            // 根据亮牌确定癞子
   541→            const wildCardInfo = this.getWildCardFromShown(shownCard);
   542→            if (wildCardInfo) {
   543→                // 在牌堆中找到对应的癞子牌
   544→                this.gameState.wildCard = this.gameState.deck.find(c =>
   545→                    c.suit === wildCardInfo.suit && c.rank === wildCardInfo.rank
   546→                ) || wildCardInfo; // 如果找不到，使用信息对象
   547→                console.log(`癞子: ${cardName(this.gameState.wildCard)} (根据亮牌${cardName(shownCard)}确定)`);
   548→            }
   549→        } else {
   550→            // 备用：随机选择
   551→            const wildIndex = total % this.gameState.deck.length;
   552→            this.gameState.wildCard = this.gameState.deck[wildIndex];
   553→            console.log(`亮牌索引超出范围，使用备用计算: ${cardName(this.gameState.wildCard)}`);
   554→        }
   555→
   556→        // 保存抓牌信息用于发牌
   557→        this.gameState.drawInfo = {
   558→            startDirection,
   559→            drawDirection,
   560→            drawPile,
   561→            totalPiles: total,
   562→            shownCard,
   563→            shownDirection,
   564→            shownPile
   565→        };
   566→    }
