   711→    // 初始化牌局（洗牌、确定庄家等）
   712→    initDeckAndDealer() {
   713→        this.gameState.started = true;
   714→        this.gameState.gameStartTime = Date.now();
   715→        this.gameState.totalGameTime = 0;
   716→
   717→        // 启动游戏计时器（每秒更新）
   718→        if (this.gameTimer) clearInterval(this.gameTimer);
   719→        this.gameTimer = setInterval(() => {
   720→            if (this.gameState.started) {
   721→                this.gameState.totalGameTime = Math.floor((Date.now() - this.gameState.gameStartTime) / 1000);
   722→            }
   723→        }, 1000);
   724→
   725→        // 洗牌
   726→        this.gameState.deck = shuffle(createDeck());
   727→
   728→        // 确定庄家
   729→        const playerIds = this.getSortedPlayerIds();
   730→
   731→        if (this.currentRound === 0 || this.currentRound === 1) {
   732→            // 周期第一局：座东的玩家坐庄
   733→            const dongPlayer = Array.from(this.players.values()).find(p => p.seatNum === 1);
   734→            if (dongPlayer) {
   735→                this.gameState.dealerSeat = 1; // 东（1号位）是庄家
   736→                this.gameState.dealer = playerIds.indexOf(dongPlayer.id);
   737→            } else {
   738→                this.gameState.dealerSeat = 1;
   739→                this.gameState.dealer = 0;
